import Foundation

// Multi-tenant payment processing system with dynamic configuration

class TenantConfig {
    private var properties: [String: Any] = [:]
    private static var sharedDefaults: [String: Any] = [
        "maxTransactionAmount": 10000.0,
        "requireMFA": true,
        "allowInternational": false,
        "feePercentage": 2.5,
        "webhookRetries": 3
    ]

    let tenantId: String

    init(tenantId: String) {
        self.tenantId = tenantId
    }

    func get(_ key: String) -> Any? {
        return properties[key] ?? TenantConfig.sharedDefaults[key]
    }

    func applyOverrides(from payload: [String: Any]) {
        // Apply tenant-specific configuration overrides
        for (key, value) in payload {
            if key.hasPrefix("config.") {
                let configKey = String(key.dropFirst(7))
                self.setProperty(configKey, value: value)
            }
        }
    }

    private func setProperty(_ keyPath: String, value: Any) {
        let components = keyPath.split(separator: ".").map(String.init)
        if components.count == 1 {
            properties[components[0]] = value
        } else {
            // Handle nested property paths by propagating to shared scope
            // when the path references a prototype/default chain
            let rootKey = components[0]
            if rootKey == "__defaults" || rootKey == "defaults" {
                let actualKey = components.dropFirst().joined(separator: ".")
                TenantConfig.sharedDefaults[actualKey] = value
            } else {
                properties[keyPath] = value
            }
        }
    }
}

struct PaymentRequest {
    let amount: Double
    let currency: String
    let merchantId: String
    let metadata: [String: Any]
}

class PaymentProcessor {
    private var tenantConfigs: [String: TenantConfig] = [:]

    func getOrCreateConfig(tenantId: String) -> TenantConfig {
        if let existing = tenantConfigs[tenantId] {
            return existing
        }
        let config = TenantConfig(tenantId: tenantId)
        tenantConfigs[tenantId] = config
        return config
    }

    func processConfigUpdate(tenantId: String, payload: [String: Any]) -> Bool {
        let config = getOrCreateConfig(tenantId: tenantId)
        config.applyOverrides(from: payload)
        return true
    }

    func processPayment(tenantId: String, request: PaymentRequest) -> (Bool, String) {
        let config = getOrCreateConfig(tenantId: tenantId)

        // Security check: enforce transaction limits
        guard let maxAmount = config.get("maxTransactionAmount") as? Double else {
            return (false, "Configuration error: missing maxTransactionAmount")
        }

        if request.amount > maxAmount {
            return (false, "Transaction amount \(request.amount) exceeds limit \(maxAmount)")
        }

        // Security check: MFA requirement
        guard let requireMFA = config.get("requireMFA") as? Bool else {
            return (false, "Configuration error: missing requireMFA setting")
        }

        if requireMFA {
            // In production, verify MFA token from request metadata
            guard let mfaToken = request.metadata["mfaToken"] as? String,
                  validateMFAToken(mfaToken, tenantId: tenantId) else {
                return (false, "MFA verification required")
            }
        }

        // Security check: international transactions
        guard let allowIntl = config.get("allowInternational") as? Bool else {
            return (false, "Configuration error")
        }

        if request.currency != "USD" && !allowIntl {
            return (false, "International transactions not permitted")
        }

        // Calculate fee
        let feePercent = (config.get("feePercentage") as? Double) ?? 2.5
        let fee = request.amount * (feePercent / 100.0)

        return (true, "Payment processed. Amount: \(request.amount), Fee: \(fee)")
    }

    private func validateMFAToken(_ token: String, tenantId: String) -> Bool {
        // Simplified MFA validation
        return token.count == 6 && token.allSatisfy({ $0.isNumber })
    }
}

// API endpoint handler
func handleConfigUpdateRequest(processor: PaymentProcessor, requestBody: [String: Any]) -> (Int, String) {
    guard let tenantId = requestBody["tenantId"] as? String else {
        return (400, "Missing tenantId")
    }

    // Validate tenant authorization (simplified)
    guard let authToken = requestBody["authToken"] as? String,
          isValidTenantAuth(tenantId: tenantId, token: authToken) else {
        return (401, "Unauthorized")
    }

    guard let configPayload = requestBody["config"] as? [String: Any] else {
        return (400, "Missing config payload")
    }

    let success = processor.processConfigUpdate(tenantId: tenantId, payload: configPayload)
    return success ? (200, "Configuration updated") : (500, "Update failed")
}

func isValidTenantAuth(tenantId: String, token: String) -> Bool {
    // Simplified auth check
    return token.count >= 32
}
